import { Accordion, Text } from "@chakra-ui/react";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface UserInputSuppressedEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const UserInputSuppressedEventInfo = ({
  event,
  onClose,
}: UserInputSuppressedEventInfoProps) => {
  const verdict = event.metadata.barge_in_verdict;
  const suppressionReason =
    event.metadata.reason ?? verdict?.reason ?? event.reason ?? "Unavailable";

  return (
    <DetailView title="User input suppressed" onClose={onClose}>
      {event.text && (
        <InfoField label="Text">
          <Text textStyle="sm" whiteSpace="pre-wrap" wordBreak="break-word">
            {event.text}
          </Text>
        </InfoField>
      )}
      <InfoField label={verdict ? "Barge-in" : "Suppression reason"}>
        <Text textStyle="sm" wordBreak="break-word">
          {suppressionReason}
        </Text>
      </InfoField>
      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
